{"code":"import random

def generate(rng):
    h = rng.randint(2, 6)
    w = rng.randint(2, 6)
    # Background is color 6; colored vertical bars/regions use 8 and 9.
    cols = []
    for x in range(w):
        cols.append(rng.choice([6, 8, 9]))
    # retain a scene with both background and at least one non-background stripe
    if all(c == 6 for c in cols):
        cols[rng.randrange(w)] = rng.choice([8, 9])
    return [[cols[x] for x in range(w)] for _ in range(h)]"}

